void deletewithchilds(BST t,int k)
{
    while(t.key != k){
        if (t.key < k){
          t = t.right;
        } else {
          t = t.left;
        }
      }

    BST p = t.left;
    while( p.right != null && p.right.right != null)
    {
      p = p.right;
    }
    BST fp = p;
    p = p.right;
    if (p == null){
    t.key = fp.key;
    t.left = fp.left;} 
    else{
    t.key = p.key;
    fp.right = p.left;
    }
} 
```

